private void lookupAttributeGroup(FormControl _control, GUPPricingAttributeSourceLevel _level)
{
    SysTableLookup          sysTableLookup;
    Query                   query;
    QueryBuildDataSource    queryBuildDataSourceView;

    query = new Query();
    sysTableLookup = SysTableLookup::newParameters(tableNum(GUPPricingattributeGroup), _control);
    queryBuildDataSourceView = query.addDataSource(tableNum(GUPPricingattributeGroup));
    queryBuildDataSourceView.addRange(fieldNum(GUPPricingattributeGroup, SourceLevel)).value(queryValue(_level));
    queryBuildDataSourceView.addRange(fieldNum(GUPPricingattributeGroup, isValid)).value(queryValue(NoYes::Yes));
    queryBuildDataSourceView.addRange(fieldNum(GUPPricingAttributeGroup, GroupType)).value(queryValue(GUPPricingAttributeGroupType::General));

    sysTableLookup.addLookupfield(fieldNum(GUPPricingattributeGroup, Name));
    sysTableLookup.addLookupfield(fieldNum(GUPPricingattributeGroup, Description));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

public void init()
{
    super();

    GUPParameters parameters = GUPParameters::find();

    // Sort the combinations by (Priority, Header type, Line type, Header name, Line name).
    GUPPriceComponentCodePriceAttributeGroupCombination_ds.query()
        .dataSourceTable(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination))
        .addSortField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority), SortOrder::Descending);

    GUPPriceComponentCodePriceAttributeGroupCombination_ds.query()
        .dataSourceTable(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination))
        .addSortField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderGroupAll), SortOrder::Ascending);

    GUPPriceComponentCodePriceAttributeGroupCombination_ds.query()
        .dataSourceName(HeaderRefPriceAttributeGroup_ds.name())
        .addSortField(fieldNum(GUPPricingAttributeGroup, Name), SortOrder::Ascending);

    GUPPriceComponentCodePriceAttributeGroupCombination_ds.query()
        .dataSourceTable(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination))
        .addSortField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LineGroupAll), SortOrder::Ascending);

    GUPPriceComponentCodePriceAttributeGroupCombination_ds.query()
        .dataSourceName(LineRefPriceAttributeGroup_ds.name())
        .addSortField(fieldNum(GUPPricingAttributeGroup, Name), SortOrder::Ascending);

}

private void changeFormLayoutByMaintenanceMode()
{
    if (GUPPriceComponentCode.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Joint)
    {
        // Priority is defined on combinations.
        DetailsTabPageHeader.visible(false);
        DetailsTabPageLine.visible(false);
        DetailsTabPageCombination.visible(true);

        GUPPriceComponentCodePriceAttributeGroupCombination_ds.allowEdit(true);
        GUPPriceComponentCodePriceAttributeGroupCombination_ds.allowCreate(true);
        GUPPriceComponentCodePriceAttributeGroupCombination_ds.allowDelete(true);

        AttributeGroup_PriorityHeaderSelection.visible(false);
        AttributeGroup_PriorityLineSelection.visible(false);
    }
    else
    {
        // Priority is defined on selections.
        DetailsTabPageHeader.visible(true);
        DetailsTabPageLine.visible(true);
        DetailsTabPageCombination.visible(true);

        GUPPriceComponentCodePriceAttributeGroupCombination_ds.allowEdit(false);
        GUPPriceComponentCodePriceAttributeGroupCombination_ds.allowCreate(false);
        GUPPriceComponentCodePriceAttributeGroupCombination_ds.allowDelete(false);

        AttributeGroup_PriorityHeaderSelection.visible(true);
        AttributeGroup_PriorityLineSelection.visible(true);
    }
}

private void changeFormLayoutByPriceComponent()
{
    switch (GUPPriceComponentCode.PriceComponent)
    {
        case GUPPriceComponent::RetailDiscounts:
            GUPPriceComponentCode_ConcurrencyMode.visible(true);
            GUPPriceComponentCode_ConcurrencyMode.allowEdit(true);
            break;

        case GUPPriceComponent::PriceMarginComponentAdjustment:
            GUPPriceComponentCode_ConcurrencyMode.visible(true);
            GUPPriceComponentCode_ConcurrencyMode.allowEdit(false);
            GUPPriceComponentCode.ConcurrencyMode = RetailDiscountConcurrency::PriceAttributeCombinationPriority;
            break;

        default:
            GUPPriceComponentCode_ConcurrencyMode.visible(false);
            GUPPriceComponentCode_ConcurrencyMode.allowEdit(false);
            GUPPriceComponentCode.ConcurrencyMode = RetailDiscountConcurrency::Exclusive;
    }
}

public int active()
{
    int ret = super();

    element.changeFormLayoutByMaintenanceMode();
    element.changeFormLayoutByPriceComponent();

    return ret;
}

public void modified()
{
    super();

    // If the record is not saved yet, show the form layout based on the selection.
    if (!GUPPriceComponentCode.RecId)
    {
        element.changeFormLayoutByMaintenanceMode();
    }
}

public void modified()
{
    super();

    // If the record is not saved yet, show the form layout based on the selection.
    if (!GUPPriceComponentCode.RecId)
    {
        element.changeFormLayoutByPriceComponent();
    }
}

public void init()
{
    super();

    QueryBuildDataSource qbdr = this.query().dataSourceTable(tableNum(GUPPriceComponentCodePriceAttributeGroupSelection));

    qbdr.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupSelection, SourceLevel))
        .value(any2Str(GUPPricingAttributeSourceLevel::Header));

    qbdr.addSortField(fieldNum(GUPPriceComponentCodePriceAttributeGroupSelection, Priority), SortOrder::Descending);
}

public void init()
{
    super();

    QueryBuildDataSource qbdr = this.query().dataSourceTable(tableNum(GUPPriceComponentCodePriceAttributeGroupSelection));

    qbdr.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupSelection, SourceLevel))
        .value(any2Str(GUPPricingAttributeSourceLevel::Line));

    qbdr.addSortField(fieldNum(GUPPriceComponentCodePriceAttributeGroupSelection, Priority), SortOrder::Descending);
}

public int active()
{
    int ret = super();

    GUPPriceComponentCodePriceAttributeGroupCombination_ds
        .object(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName))
        .allowEdit(GUPPriceComponentCodePriceAttributeGroupCombination.HeaderGroupAll == GUPGroupAll::Group);

    GUPPriceComponentCodePriceAttributeGroupCombination_ds
            .object(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroupName))
            .allowEdit(GUPPriceComponentCodePriceAttributeGroupCombination.LineGroupAll == GUPGroupAll::Group);

    return ret;
}

public void modified()
{
    super();

    GUPPriceComponentCodePriceAttributeGroupCombination_ds
        .object(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName))
        .allowEdit(GUPPriceComponentCodePriceAttributeGroupCombination.HeaderGroupAll == GUPGroupAll::Group);

    if (GUPPriceComponentCodePriceAttributeGroupCombination.HeaderGroupAll == GUPGroupAll::All)
    {
        GUPPriceComponentCodePriceAttributeGroupCombination.HeaderPriceAttributeGroupName = '';
    }
}

public void modified()
{
    super();

    GUPPriceComponentCodePriceAttributeGroupCombination_ds
        .object(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroupName))
        .allowEdit(GUPPriceComponentCodePriceAttributeGroupCombination.LineGroupAll == GUPGroupAll::Group);

    if (GUPPriceComponentCodePriceAttributeGroupCombination.LineGroupAll == GUPGroupAll::All)
    {
        GUPPriceComponentCodePriceAttributeGroupCombination.LinePriceAttributeGroupName = '';
    }
}
